import{_ as e,H as d,f as o,i as r}from"./chunks/framework.CBmkDW73.js";const g=JSON.parse('{"title":"规范评审员关卡 (Spec Reviewers)","description":"","frontmatter":{},"headers":[],"relativePath":"zh/skills/reviewers.md","filePath":"zh/skills/reviewers.md"}'),c={name:"zh/skills/reviewers.md"};function a(s,t,n,i,l,p){return d(),o("div",null,[...t[0]||(t[0]=[r('<h1 id="规范评审员关卡-spec-reviewers" tabindex="-1">规范评审员关卡 (Spec Reviewers) <a class="header-anchor" href="#规范评审员关卡-spec-reviewers" aria-label="Permalink to &quot;规范评审员关卡 (Spec Reviewers)&quot;">​</a></h1><p>规范评审员协议（<code>skills/references/reviewers.md</code>）规定了在 <code>design</code> 阶段写完暂存规范并提交给 <code>plan</code> 之前执行的并行评审关卡。</p><h2 id="触发式匹配机制" tabindex="-1">触发式匹配机制 <a class="header-anchor" href="#触发式匹配机制" aria-label="Permalink to &quot;触发式匹配机制&quot;">​</a></h2><p>运行所有符合当前规范特征的评审员。条件可累加；若仅基线规则 1 命中，则只派发 <code>spec-compliance</code>。</p><table tabindex="0"><thead><tr><th>#</th><th>触发条件</th><th>派发的评审员</th><th>模型分级</th><th>审查职责</th></tr></thead><tbody><tr><td>1</td><td><strong>始终触发</strong>（基线）</td><td><code>spec-compliance</code></td><td><code>balanced</code></td><td>验证每个 <code>contract:</code>/<code>invariant:</code> 都有对应验收 <code>test:</code>，失效模式与作用域边界明确，数据形状具体。</td></tr><tr><td>2</td><td>定义 <strong>≥3 个状态枚举或状态机</strong></td><td><code>state-machine</code></td><td><code>strongest</code></td><td>枚举所有合法状态迁移；标记缺失边、死状态/不可达状态及未声明的初态/终态。</td></tr><tr><td>3</td><td>含 <strong>≥2 条交叉引用同一行为的规则</strong></td><td><code>consistency</code></td><td><code>strongest</code></td><td>检测相互矛盾、未定义优先级、不完整例外列表及正文与表格不一致之处。</td></tr><tr><td>4</td><td><strong><code>topology=multi-module</code> 或声明共享契约</strong></td><td><code>boundary</code></td><td><code>balanced</code></td><td>验证共享契约单一归属、显式版本规则、序列化兼容性及跨模块假设。</td></tr><tr><td>5</td><td>涉及 <strong>持久化写入、外部副作用或提交语义</strong></td><td><code>safety</code></td><td><code>strongest</code></td><td>追踪每条写入路径；检查崩溃恢复缺口、并发覆盖写、部分提交及原子性边界。</td></tr><tr><td>6</td><td><strong><code>scope=complex</code> 或预计派发 Subagent 并行实现</strong></td><td><code>implementability</code></td><td><code>balanced</code></td><td>以首次接手开发者视角审阅；标记未定义数据结构、模糊顺序、未指定错误处理及缺省语义。</td></tr></tbody></table><p>模型分级解析顺序：项目 <code>.praxis/model-tiers.yaml</code> → 用户 <code>~/.praxis/model-tiers.yaml</code> → 宿主默认模型（读取 <code>tiers.&lt;tier&gt;.model</code>）。</p><h2 id="并行执行与-coordinator-批判性合成" tabindex="-1">并行执行与 Coordinator 批判性合成 <a class="header-anchor" href="#并行执行与-coordinator-批判性合成" aria-label="Permalink to &quot;并行执行与 Coordinator 批判性合成&quot;">​</a></h2><ol><li><strong>并行派发</strong>：所有被触发的评审员作为独立子智能体（Subagent）并行运行，仅传入规范文件路径（<code>docs/staging/specs/YYYY-MM-DD-&lt;topic&gt;.md</code>），逐行输出 <code>BLOCK | GAP | CONFLICT</code>。</li><li><strong>Coordinator 合成</strong>：仅执行一轮。主智能体批判性评估每条发现、裁决冲突、识别视角盲区、判定严重级别（<code>BLOCK</code> 或附带理由的 <code>DEFER</code>），一次性修补规范并向用户汇报。评审员提供建议，Coordinator 做出最终裁决。</li></ol>',8)])])}const m=e(c,[["render",a]]);export{g as __pageData,m as default};
